# The fix in action: find a wall, put it on the right, then follow it out of the room.
def _side_is_wall(world, robot, turn):
    i = (HEADINGS.index(robot["facing"]) + turn) % 4
    dr, dc = STEP[HEADINGS[i]]
    return world[robot["row"] + dr][robot["col"] + dc] == "#"
