_out = False
for _ in range(200):
    if not _side_is_wall(ROOM, r, 1):
        r["facing"] = HEADINGS[(HEADINGS.index(r["facing"]) + 1) % 4]
        forward(r)
    elif not _side_is_wall(ROOM, r, 0):
        forward(r)
